package com.bank.datefn.service;
import com.bank.datefn.model.Txn;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.logging.*;
import java.util.stream.*;

public class StatementService {
    private static final Logger log = Logger.getLogger(StatementService.class.getName());
    static {
        Handler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false); log.addHandler(h);
    }
    private final List<Txn> rows;
    public StatementService(List<Txn> rows) { this.rows = rows; }

    // SLOW: like EXTRACT(MONTH) = 10 — must inspect every row
    public List<Txn> slowByExtract(String acct, int year, int month) {
        int[] touched = {0};
        List<Txn> out = rows.stream()
            .peek(t -> touched[0]++)
            .filter(t -> t.getAccountId().equals(acct)
                && t.getTs().getYear() == year && t.getTs().getMonthValue() == month)
            .collect(Collectors.toList());
        log.info(() -> "slowByExtract touched=" + touched[0]);
        return out;
    }

    // FAST: DATE_TRUNC range — compare the bare ts to [start, nextMonth)
    public List<Txn> fastByRange(String acct, LocalDate anyDayInMonth) {
        LocalDateTime start = anyDayInMonth.withDayOfMonth(1).atStartOfDay(); // DATE_TRUNC('month', ...)
        LocalDateTime end = start.plusMonths(1);                               // + INTERVAL '1 month'
        int[] touched = {0};
        List<Txn> out = rows.stream()
            .peek(t -> touched[0]++)
            .filter(t -> t.getAccountId().equals(acct)
                && !t.getTs().isBefore(start) && t.getTs().isBefore(end))
            .collect(Collectors.toList());
        log.info(() -> "fastByRange [" + start + "," + end + ") touched=" + touched[0]);
        return out;
    }
}
