package com.bank.datefn;
import com.bank.datefn.model.Txn;
import com.bank.datefn.service.StatementService;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.logging.*;

public class DateFnDemo {
    public static void main(String[] args) {
        List<Txn> rows = List.of(
            new Txn("SAV2001", new BigDecimal("1000"), LocalDateTime.of(2026,10,5,9,0)),
            new Txn("SAV2001", new BigDecimal("2000"), LocalDateTime.of(2026,10,20,9,0)),
            new Txn("SAV2001", new BigDecimal("3000"), LocalDateTime.of(2026,11,1,0,0)),
            new Txn("CUR3001", new BigDecimal("500"),  LocalDateTime.of(2026,10,10,9,0)));
        StatementService svc = new StatementService(rows);
        System.out.println("extract -> " + svc.slowByExtract("SAV2001", 2026, 10).size());
        System.out.println("range   -> " + svc.fastByRange("SAV2001", LocalDate.of(2026,10,15)).size());
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
